from lib import *
S = SS('n35')
steps = [
    step("同一份数据(含 <b>a&b</b>、中文、emoji、U+2028)用六种方法渲染:JSON 92 字节,HTML 字符转义成 \\u003c \\u0026,中文和 emoji 原样,Content-Type 为 application/json; charset=utf-8;IndentedJSON 117 字节,4 空格缩进;PureJSON 68 字节,HTML 字符不转义,末尾多一个换行(Encoder 的行为);AsciiJSON 101 字节,Content-Type 只是 application/json(没有 charset),非 ASCII 全部转成 \\u 转义;SecureJSON 对对象与 JSON 相同;JSONP 带 callback 时为 cb({…});,Content-Type 变成 application/javascript; charset=utf-8。所有变体里 U+2028 都被转成 \\u2028。", t=tl(S(1)), mark=lidx(S(1), '/pure', '/ascii', '/jsonp?callback=cb'), done=lidx(S(1), '/json  ', '/indent', '/secure'), b=bars([['JSON', 92, '92 字节'], ['IndentedJSON', 117, '117 字节'], ['PureJSON', 68, '68 字节(+1 换行)'], ['AsciiJSON', 101, '101 字节'], ['SecureJSON', 92, '92 字节'], ['JSONP(cb)', 97, '97 字节']], 117, done=[0, 1, 4], mark=[2, 3, 5]), kv=KV([['JSON / Secure', 'HTML 字符被转义'], ['PureJSON', '不转义 HTML,末尾 + 换行'], ['AsciiJSON', '非 ASCII 全转 \\u,没有 charset']], ['PureJSON'])),
    step("转义规则与往返检查:JSON 把 < > & 转成 \\u003c 等,中文原样,标准解析器往返一致;PureJSON 不转义 HTML 字符,往返一致;AsciiJSON 转义 HTML 字符与非 ASCII,中文往返一致,但 emoji 不一致——它被写成 \\u1f600(源码里按 rune 用 \\\\u%04x,超过 0xFFFF 的字符变成 5 位十六进制,不是合法的 JSON 转义),标准解析器读成 \"ὠ0\" 而不是 \"😀\"。", t=tl(S(2)), mark=lidx(S(2), '/ascii', 'AsciiJSON 输出里 emoji 那一段', 'if r > unicode.MaxASCII'), done=lidx(S(2), '/json ', '/pure '), kv=KV([['AsciiJSON 的 emoji', '\\u1f600,标准解析器读成 "ὠ0"'], ['原因', '按 rune 输出 \\u%04x,不拆代理对'], ['PureJSON', '不转义 HTML 字符']], ['AsciiJSON 的 emoji'])),
    step("SecureJSON 只对“顶层是数组”加前缀:对象 {\"a\":1} 原样;[1,2] → while(1);[1,2];空数组 [] 也加;嵌套在对象里的数组不加;顶层是字符串 \"[x]\" 不加(判断的是序列化后以 [ 开头、以 ] 结尾)。前缀可以用 r.SecureJsonPrefix(…) 改成 )]}',\\n。", t=tl(S(3)), mark=lidx(S(3), '/arr', '/empty'), done=lidx(S(3), '/obj', '/nested', '/str', 'SecureJsonPrefix'), kv=KV([['顶层数组', '加前缀 while(1);'], ['对象 / 嵌套数组 / 字符串', '不加'], ['改前缀', 'r.SecureJsonPrefix(...)']], ['顶层数组'])),
    step("JSONP:没有 callback 参数就是普通 JSON(Content-Type 为 application/json);callback=cb → cb({…});callback=app.handle 点号原样;callback=a(1)%3Bb 解码后是 a(1);b,输出 a(1);b({…});——圆括号、分号都不处理;<script> 被 JSEscapeString 转成 \\u003C…,引号被转义成 \\' 与 \\\"。callback 只经过 JSEscapeString,没有别的校验,用 JSONP 时要自己限制成标识符。", t=tl(S(4)), mark=lidx(S(4), 'a(1)%3Bb', '%3Cscript%3E', 'x%27y%22z'), done=lidx(S(4), '/p   ', 'callback=cb', 'app.handle'), kv=KV([['无 callback', '普通 JSON'], ['括号 / 分号', '原样输出,不校验'], ['< > 引号', '被 JSEscapeString 转义']], ['括号 / 分号'])),
    step("序列化失败时 c.JSON 的表现:channel 与 NaN 都不能序列化——响应是状态 200、Content-Type 已设成 application/json、正文为空,c.Errors 里有一条(json: unsupported type: chan int / json: unsupported value: NaN);Render 失败只是 c.Error 并 Abort,不会自动变成 500。", t=tl(S(5)), mark=lidx(S(5), '/ch', '/nan'), done=lidx(S(5), '/ok'), kv=KV([['失败时', '200 + 空正文 + c.Errors'], ['不会', '自动改成 500'], ['对策', '错误处理中间件里检查 c.Errors 与 Written()']], ['失败时'])),
]
A = mkartn('n35', 35, 'Gin,JSON渲染,PureJSON,AsciiJSON,SecureJSON,JSONP,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 JSON 的六种渲染:同一份数据的输出字节与 Content-Type;PureJSON 不转义 HTML 字符(68 字节对 92 字节)、末尾多一个换行;AsciiJSON 把 emoji 写成非法的 \\u1f600(标准解析器读回 "ὠ0");SecureJSON 只给顶层数组加前缀;JSONP 的 callback 只做 JS 转义;序列化失败时是 200 加空正文。',
    'c.JSON、IndentedJSON、PureJSON、AsciiJSON、SecureJSON、JSONP 到底有什么区别?同一份含 HTML 字符、中文、emoji 的数据,它们各自输出什么字节?这篇逐个对比,顺带发现了 AsciiJSON 对 emoji 的一个问题,以及序列化失败时 200 加空正文的行为。',
    [('\\u1f600', 'AsciiJSON 对 😀 的输出——不是合法的 JSON 转义,标准解析器读回 "ὠ0"'), ('68 vs 92 字节', '同一份数据 PureJSON 与 JSON 的输出长度(不转义 HTML 字符)'), ('200 + 空正文', 'c.JSON 序列化失败(channel / NaN)时的响应')],
    [('六种渲染的差别', '<p><code>c.JSON</code> 用 <code>json.Marshal</code>,所以 <code>&lt; &gt; &amp;</code> 会被转成 <code>\\u003c</code> 这样的转义(为了在 HTML 里内嵌更安全),这也是 API 输出里常见的“乱码”。<code>PureJSON</code> 关闭了这个转义,输出更短也更易读,但 Encoder 会在末尾加一个换行。<code>IndentedJSON</code> 只是带缩进,官方也只推荐开发时使用。</p>'),
     ('AsciiJSON 的 emoji', '<p><code>AsciiJSON</code> 把所有非 ASCII 字符转成 <code>\\uXXXX</code>,对中文是对的(<code>\\u4e2d\\u6587</code>);但源码是按 rune 用 <code>\\u%04x</code> 输出的,超过 0xFFFF 的字符(emoji)需要拆成代理对,这里却输出了 5 位的 <code>\\u1f600</code>,标准解析器读成 <code>\\u1f60</code> 加字符 <code>0</code>。如果你的数据里可能有 emoji,不要用 <code>AsciiJSON</code>,或者自己处理。Content-Type 也没有带 charset。</p>'),
     ('SecureJSON', '<p>它针对的是早期浏览器里的 JSON 劫持(文档的说法,本文没有验证这个攻击):对序列化结果以 <code>[</code> 开头、以 <code>]</code> 结尾的情形加一个 <code>while(1);</code> 前缀。对象、嵌套数组、字符串都不加。客户端必须先去掉前缀才能解析,所以只有你同时控制客户端时才有意义。</p>'),
     ('JSONP', '<p>JSONP 把 JSON 包成 <code>callback(...)</code> 返回给 <code>&lt;script&gt;</code> 标签。Gin 对 callback 只做 <code>JSEscapeString</code>(转义引号、尖括号等),圆括号、点号、分号都原样输出,所以 <code>a(1);b</code> 这样的值也会被写进响应。需要 JSONP 时请自己用正则把 callback 限制成合法的标识符,并优先使用 CORS。</p>'),
     ('序列化失败', '<p>Gin 的 <code>Render</code> 失败时只是 <code>c.Error(err)</code> 并 <code>Abort</code>,没有改状态码:此时 Content-Type 已经设好、状态是 200、正文是空的。想把它变成 500,要在统一的错误处理中间件里检查 <code>c.Errors</code> 和 <code>c.Writer.Written()</code>(见错误收集一篇)。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP;JSON 编解码用 Gin 默认的 encoding/json;往返检查用标准库的 json.Unmarshal;AsciiJSON 的源码行号来自模块缓存;每种情形各一次',
     '没有验证:用 sonic、jsoniter 等替代 JSON 库(构建标签)时六种渲染的输出差别;AsciiJSON 的问题是否在更新的 Gin 版本中已修复(只测了 v1.12.0);JSONP 在浏览器里的实际行为;大对象下 IndentedJSON 与 JSON 的耗时对比'],
    'JSON 渲染')
